=== FILE: apb_regs.v ===
// apb_regs: four 32-bit read/write registers behind an APB4 completer port.
// Implements interface_spec.md per microarchitecture.md (zero wait states,
// no state machine, PSLVERR policy for unmapped addresses).
`timescale 1ns / 1ps
`default_nettype none

module apb_regs #(
    parameter ADDR_WIDTH = 8,
    parameter DATA_WIDTH = 32
) (
    input  wire                    pclk,
    input  wire                    presetn,
    input  wire [ADDR_WIDTH-1:0]   paddr,
    input  wire                    psel,
    input  wire                    penable,
    input  wire                    pwrite,
    input  wire [DATA_WIDTH-1:0]   pwdata,
    input  wire [DATA_WIDTH/8-1:0] pstrb,
    output wire [DATA_WIDTH-1:0]   prdata,
    output wire                    pready,
    output wire                    pslverr
);

    localparam STRB_WIDTH = DATA_WIDTH / 8;

    // ------------------------------------------------------------------
    // Decode (microarchitecture section 3)
    // ------------------------------------------------------------------
    wire       access = psel && penable;
    wire       mapped = (paddr[1:0] == 2'b00) &&
                        (paddr[ADDR_WIDTH-1:4] == {(ADDR_WIDTH-4){1'b0}});
    wire [1:0] idx    = paddr[3:2];
    wire       wr_en  = access && pwrite && mapped;
    wire       rd_en  = access && !pwrite && mapped;

    // ------------------------------------------------------------------
    // Register file (microarchitecture section 2)
    // ------------------------------------------------------------------
    reg  [DATA_WIDTH-1:0] reg0;
    reg  [DATA_WIDTH-1:0] reg1;
    reg  [DATA_WIDTH-1:0] reg2;
    reg  [DATA_WIDTH-1:0] reg3;
    reg  [DATA_WIDTH-1:0] reg0_d;
    reg  [DATA_WIDTH-1:0] reg1_d;
    reg  [DATA_WIDTH-1:0] reg2_d;
    reg  [DATA_WIDTH-1:0] reg3_d;
    reg  [DATA_WIDTH-1:0] rdata_sel;
    wire [DATA_WIDTH-1:0] wdata_merged;

    // Addressed register (read multiplexer, also the old value for merge)
    always @* begin
        case (idx)
            2'd0:    rdata_sel = reg0;
            2'd1:    rdata_sel = reg1;
            2'd2:    rdata_sel = reg2;
            2'd3:    rdata_sel = reg3;
            default: rdata_sel = {DATA_WIDTH{1'b0}};
        endcase
    end

    // Byte merge: strobed lanes take pwdata, other lanes keep the old value
    genvar lane;
    generate
        for (lane = 0; lane < STRB_WIDTH; lane = lane + 1) begin : g_lane
            assign wdata_merged[8*lane +: 8] =
                pstrb[lane] ? pwdata[8*lane +: 8] : rdata_sel[8*lane +: 8];
        end
    endgenerate

    // Next state
    always @* begin
        reg0_d = reg0;
        reg1_d = reg1;
        reg2_d = reg2;
        reg3_d = reg3;
        if (wr_en) begin
            case (idx)
                2'd0:    reg0_d = wdata_merged;
                2'd1:    reg1_d = wdata_merged;
                2'd2:    reg2_d = wdata_merged;
                2'd3:    reg3_d = wdata_merged;
                default: begin end
            endcase
        end
    end

    // State: synchronous active-low reset to zero (microarchitecture section 5)
    always @(posedge pclk) begin
        if (!presetn) begin
            reg0 <= {DATA_WIDTH{1'b0}};
            reg1 <= {DATA_WIDTH{1'b0}};
            reg2 <= {DATA_WIDTH{1'b0}};
            reg3 <= {DATA_WIDTH{1'b0}};
        end else begin
            reg0 <= reg0_d;
            reg1 <= reg1_d;
            reg2 <= reg2_d;
            reg3 <= reg3_d;
        end
    end

    // ------------------------------------------------------------------
    // Responses (microarchitecture sections 1, 3, 4)
    // ------------------------------------------------------------------
    assign prdata  = rd_en ? rdata_sel : {DATA_WIDTH{1'b0}};
    assign pready  = 1'b1;
    assign pslverr = access && !mapped;

`ifdef FORMAL
    // ------------------------------------------------------------------
    // Design-intent properties (default parameters only)
    // Decode and merge here are written independently of the RTL above.
    // ------------------------------------------------------------------
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge pclk) f_past_valid <= 1'b1;

    wire        f_access = psel && penable;
    wire        f_wr     = f_access && pwrite;
    wire        f_is0    = (paddr == 8'h00);
    wire        f_is1    = (paddr == 8'h04);
    wire        f_is2    = (paddr == 8'h08);
    wire        f_is3    = (paddr == 8'h0C);
    wire        f_mapped = f_is0 || f_is1 || f_is2 || f_is3;
    wire [31:0] f_mask   = {{8{pstrb[3]}}, {8{pstrb[2]}},
                            {8{pstrb[1]}}, {8{pstrb[0]}}};
    wire [31:0] f_next0  = (f_wr && f_is0) ? ((reg0 & ~f_mask) | (pwdata & f_mask)) : reg0;
    wire [31:0] f_next1  = (f_wr && f_is1) ? ((reg1 & ~f_mask) | (pwdata & f_mask)) : reg1;
    wire [31:0] f_next2  = (f_wr && f_is2) ? ((reg2 & ~f_mask) | (pwdata & f_mask)) : reg2;
    wire [31:0] f_next3  = (f_wr && f_is3) ? ((reg3 & ~f_mask) | (pwdata & f_mask)) : reg3;

    // Manager assumptions: reset first, no transfer in reset,
    // setup then access, stable request through access.
    always @(*) begin
        if (!f_past_valid) assume(!presetn);
        if (!presetn)      assume(!psel);
        if (penable)       assume(psel);
    end

    always @(posedge pclk) begin
        if (f_past_valid) begin
            if (psel && penable) begin
                assume($past(psel) && !$past(penable));
                assume(paddr  == $past(paddr));
                assume(pwrite == $past(pwrite));
                assume(pwdata == $past(pwdata));
                assume(pstrb  == $past(pstrb));
            end
            if ($past(psel) && !$past(penable) && presetn)
                assume(psel && penable);
        end
    end

    // Response assertions
    always @(*) begin
        assert(pready == 1'b1);
        if (!f_access) begin
            assert(prdata == 32'h0);
            assert(pslverr == 1'b0);
        end else begin
            assert(pslverr == !f_mapped);
            if (pwrite || !f_mapped) assert(prdata == 32'h0);
            if (!pwrite && f_is0)    assert(prdata == reg0);
            if (!pwrite && f_is1)    assert(prdata == reg1);
            if (!pwrite && f_is2)    assert(prdata == reg2);
            if (!pwrite && f_is3)    assert(prdata == reg3);
        end
    end

    // Register assertions: zero after reset; otherwise change only in a
    // mapped write access, only in strobed bytes, to the written data.
    always @(posedge pclk) begin
        if (f_past_valid) begin
            if (!$past(presetn)) begin
                assert(reg0 == 32'h0);
                assert(reg1 == 32'h0);
                assert(reg2 == 32'h0);
                assert(reg3 == 32'h0);
            end else begin
                assert(reg0 == $past(f_next0));
                assert(reg1 == $past(f_next1));
                assert(reg2 == $past(f_next2));
                assert(reg3 == $past(f_next3));
            end
        end
    end

    // Covers: each register written and read back, a partial write,
    // unmapped read and write errors.
    always @(posedge pclk) begin
        if (f_past_valid && presetn) begin
            cover(f_access && !pwrite && f_is0 && (prdata != 32'h0));
            cover(f_access && !pwrite && f_is1 && (prdata != 32'h0));
            cover(f_access && !pwrite && f_is2 && (prdata != 32'h0));
            cover(f_access && !pwrite && f_is3 && (prdata != 32'h0));
            cover(f_wr && f_mapped && (pstrb == 4'b0101));
            cover(f_access && !pwrite && !f_mapped && pslverr);
            cover(f_wr && !f_mapped && pslverr);
        end
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
=== FILE: apb_regs_tb.v ===
// apb_regs_tb: self-checking testbench for apb_regs.
// Inputs are driven after the falling edge; outputs are sampled 1 ns later,
// before the rising edge. Every failed check is reported with $error.
`timescale 1ns / 1ps
`default_nettype none

`define TB_CHECK(cond, msg) \
    begin \
        if (cond) passed = passed + 1; \
        else begin \
            failed = failed + 1; \
            $error msg; \
        end \
    end

module apb_regs_tb;

    reg         pclk;
    reg         presetn;
    reg  [7:0]  paddr;
    reg         psel;
    reg         penable;
    reg         pwrite;
    reg  [31:0] pwdata;
    reg  [3:0]  pstrb;
    wire [31:0] prdata;
    wire        pready;
    wire        pslverr;

    integer passed;
    integer failed;
    integer i;
    integer j;
    integer k;
    integer g;
    integer gap;
    reg [8*64-1:0] nonce;
    reg [31:0]     model [0:3];
    reg [31:0]     rnd;
    reg [31:0]     rnd2;
    reg [7:0]      addr;

    apb_regs dut (
        .pclk    (pclk),
        .presetn (presetn),
        .paddr   (paddr),
        .psel    (psel),
        .penable (penable),
        .pwrite  (pwrite),
        .pwdata  (pwdata),
        .pstrb   (pstrb),
        .prdata  (prdata),
        .pready  (pready),
        .pslverr (pslverr)
    );

    initial pclk = 1'b0;
    always #5 pclk = ~pclk;

    // Expected decode: mapped only at the four aligned register offsets.
    function tb_mapped;
        input [7:0] a;
        begin
            tb_mapped = (a == 8'h00) || (a == 8'h04) || (a == 8'h08) || (a == 8'h0C);
        end
    endfunction

    // Expected byte merge.
    function [31:0] tb_merge;
        input [31:0] old;
        input [31:0] d;
        input [3:0]  s;
        begin
            tb_merge[7:0]   = s[0] ? d[7:0]   : old[7:0];
            tb_merge[15:8]  = s[1] ? d[15:8]  : old[15:8];
            tb_merge[23:16] = s[2] ? d[23:16] : old[23:16];
            tb_merge[31:24] = s[3] ? d[31:24] : old[31:24];
        end
    endfunction

    // One idle cycle with arbitrary request lines; responses must be quiet.
    task idle;
        input [7:0] a;
        input       w;
        begin
            @(negedge pclk);
            psel    = 1'b0;
            penable = 1'b0;
            pwrite  = w;
            paddr   = a;
            pwdata  = 32'hDEAD_BEEF;
            pstrb   = 4'hF;
            #1;
            `TB_CHECK(prdata === 32'h0, ("idle (paddr %h): prdata %h expected 0", a, prdata))
            `TB_CHECK(pslverr === 1'b0, ("idle (paddr %h): pslverr %b expected 0", a, pslverr))
        end
    endtask

    // One write transfer: setup then access. Leaves the access phase driven;
    // the caller follows with another transfer or an idle cycle.
    task apb_write;
        input [7:0]  a;
        input [31:0] d;
        input [3:0]  s;
        reg          exp_err;
        begin
            exp_err = !tb_mapped(a);
            @(negedge pclk);
            psel    = 1'b1;
            penable = 1'b0;
            pwrite  = 1'b1;
            paddr   = a;
            pwdata  = d;
            pstrb   = s;
            #1;
            `TB_CHECK(prdata === 32'h0, ("write setup %h: prdata %h not quiet", a, prdata))
            `TB_CHECK(pslverr === 1'b0, ("write setup %h: pslverr %b not quiet", a, pslverr))
            @(negedge pclk);
            penable = 1'b1;
            #1;
            `TB_CHECK(pready === 1'b1, ("write access %h: pready %b (wait state)", a, pready))
            `TB_CHECK(pslverr === exp_err, ("write access %h: pslverr %b expected %b", a, pslverr, exp_err))
            `TB_CHECK(prdata === 32'h0, ("write access %h: prdata %h expected 0", a, prdata))
            if (!exp_err) model[a[3:2]] = tb_merge(model[a[3:2]], d, s);
        end
    endtask

    // One read transfer: setup then access.
    task apb_read;
        input [7:0] a;
        reg         exp_err;
        reg [31:0]  exp_data;
        begin
            exp_err  = !tb_mapped(a);
            exp_data = exp_err ? 32'h0 : model[a[3:2]];
            @(negedge pclk);
            psel    = 1'b1;
            penable = 1'b0;
            pwrite  = 1'b0;
            paddr   = a;
            pwdata  = 32'hFFFF_FFFF;
            pstrb   = 4'h0;
            #1;
            `TB_CHECK(prdata === 32'h0, ("read setup %h: prdata %h not quiet", a, prdata))
            `TB_CHECK(pslverr === 1'b0, ("read setup %h: pslverr %b not quiet", a, pslverr))
            @(negedge pclk);
            penable = 1'b1;
            #1;
            `TB_CHECK(pready === 1'b1, ("read access %h: pready %b (wait state)", a, pready))
            `TB_CHECK(pslverr === exp_err, ("read access %h: pslverr %b expected %b", a, pslverr, exp_err))
            `TB_CHECK(prdata === exp_data, ("read access %h: prdata %h expected %h", a, prdata, exp_data))
        end
    endtask

    // Hold reset for n rising edges with psel low, then release.
    task do_reset;
        input [31:0] n;
        begin
            @(negedge pclk);
            presetn = 1'b0;
            psel    = 1'b0;
            penable = 1'b0;
            pwrite  = 1'b0;
            paddr   = 8'h00;
            pwdata  = 32'h0;
            pstrb   = 4'h0;
            for (j = 0; j < n; j = j + 1) begin
                #1;
                `TB_CHECK(prdata === 32'h0, ("reset: prdata %h expected 0", prdata))
                `TB_CHECK(pslverr === 1'b0, ("reset: pslverr %b expected 0", pslverr))
                `TB_CHECK(pready === 1'b1, ("reset: pready %b expected 1", pready))
                @(negedge pclk);
            end
            presetn = 1'b1;
            model[2'd0] = 32'h0;
            model[2'd1] = 32'h0;
            model[2'd2] = 32'h0;
            model[2'd3] = 32'h0;
        end
    endtask

    task read_all;
        begin
            apb_read(8'h00);
            apb_read(8'h04);
            apb_read(8'h08);
            apb_read(8'h0C);
        end
    endtask

    initial begin
        passed = 0;
        failed = 0;
        nonce  = {64{8'h00}};
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) begin
            $display("apb_regs_tb: no +nirmaan_nonce given");
        end

        presetn = 1'b0;
        psel    = 1'b0;
        penable = 1'b0;
        pwrite  = 1'b0;
        paddr   = 8'h00;
        pwdata  = 32'h0;
        pstrb   = 4'h0;
        for (i = 0; i < 4; i = i + 1) model[i[1:0]] = 32'h0;

        // T1: reset values, back-to-back reads
        do_reset(32'd3);
        idle(8'h00, 1'b0);
        idle(8'h0C, 1'b1);
        read_all;
        idle(8'h04, 1'b0);

        // T2: full-word writes back to back, then reads back to back
        apb_write(8'h00, 32'hA5A5_5A5A, 4'hF);
        apb_write(8'h04, 32'h0123_4567, 4'hF);
        apb_write(8'h08, 32'h89AB_CDEF, 4'hF);
        apb_write(8'h0C, 32'hFEDC_BA98, 4'hF);
        read_all;
        `TB_CHECK(model[2'd0] === 32'hA5A5_5A5A, ("model REG0 %h", model[2'd0]))
        `TB_CHECK(model[2'd3] === 32'hFEDC_BA98, ("model REG3 %h", model[2'd3]))
        idle(8'h10, 1'b1);
        idle(8'h00, 1'b1);
        idle(8'h08, 1'b0);

        // T3: write then read of every register, idle gaps of 0..3 between pairs
        for (i = 0; i < 4; i = i + 1) begin
            rnd = $random;
            apb_write({4'h0, i[1:0], 2'b00}, rnd, 4'hF);
            apb_read({4'h0, i[1:0], 2'b00});
            for (g = 0; g < i; g = g + 1) idle(rnd[7:0], rnd[8]);
        end
        idle(8'h00, 1'b0);

        // T4: directed partial writes with literal expectations
        apb_write(8'h04, 32'h0000_0000, 4'hF);
        apb_write(8'h04, 32'hFFFF_FFFF, 4'b0001);
        apb_read(8'h04);
        `TB_CHECK(model[2'd1] === 32'h0000_00FF, ("strobe 0001: model %h", model[2'd1]))
        apb_write(8'h04, 32'hFFFF_FFFF, 4'b0100);
        apb_read(8'h04);
        `TB_CHECK(model[2'd1] === 32'h00FF_00FF, ("strobe 0100: model %h", model[2'd1]))
        apb_write(8'h04, 32'hAABB_CCDD, 4'b1010);
        apb_read(8'h04);
        `TB_CHECK(model[2'd1] === 32'hAAFF_CCFF, ("strobe 1010: model %h", model[2'd1]))
        apb_write(8'h04, 32'h1122_3344, 4'b0000);
        apb_read(8'h04);
        `TB_CHECK(model[2'd1] === 32'hAAFF_CCFF, ("strobe 0000: model %h", model[2'd1]))
        idle(8'h04, 1'b1);

        // T5: every strobe pattern on every register
        for (i = 0; i < 4; i = i + 1) begin
            for (k = 0; k < 16; k = k + 1) begin
                rnd = $random;
                apb_write({4'h0, i[1:0], 2'b00}, rnd, k[3:0]);
                apb_read({4'h0, i[1:0], 2'b00});
            end
        end
        idle(8'h00, 1'b0);

        // T6: exhaustive address sweep (misaligned, out of range, aliases)
        for (i = 0; i < 256; i = i + 1) begin
            apb_write(i[7:0], {i[7:0], ~i[7:0], 16'hC0DE}, 4'hF);
        end
        idle(8'hFF, 1'b1);
        for (i = 0; i < 256; i = i + 1) begin
            apb_read(i[7:0]);
        end
        `TB_CHECK(model[2'd0] === 32'h00FF_C0DE, ("sweep: model REG0 %h", model[2'd0]))
        `TB_CHECK(model[2'd3] === 32'h0CF3_C0DE, ("sweep: model REG3 %h", model[2'd3]))
        read_all;
        idle(8'h00, 1'b0);

        // T7: random traffic with random idle gaps
        for (i = 0; i < 300; i = i + 1) begin
            rnd  = $random;
            rnd2 = $random;
            addr = rnd[8] ? {4'h0, rnd[1:0], 2'b00} : rnd[7:0];
            if (rnd[9]) apb_write(addr, rnd2, rnd[13:10]);
            else        apb_read(addr);
            gap = {30'd0, rnd[15:14]};
            for (g = 0; g < gap; g = g + 1) idle(rnd2[7:0], rnd[16]);
        end
        idle(8'h00, 1'b0);
        read_all;
        idle(8'h00, 1'b0);

        // T8: reset again after traffic
        apb_write(8'h00, 32'h1111_1111, 4'hF);
        apb_write(8'h04, 32'h2222_2222, 4'hF);
        apb_write(8'h08, 32'h3333_3333, 4'hF);
        apb_write(8'h0C, 32'h4444_4444, 4'hF);
        read_all;
        idle(8'h00, 1'b0);
        do_reset(32'd2);
        idle(8'h00, 1'b0);
        read_all;
        idle(8'h00, 1'b0);
        idle(8'h00, 1'b0);

        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule

